// Library model
// ---------------------------------------------------------------------------

export type ExampleCategory = 'gpio' | 'serial' | 'display' | 'sensor' | 'motor' | 'analog'
export type ExampleDifficulty = 'beginner' | 'intermediate' | 'advanced'
export type ExampleInstrument = 'uart' | 'logic' | 'scope'

/** Library sections in display order. */
export const EXAMPLE_CATEGORIES: readonly ExampleCategory[] = ['gpio', 'serial', 'display', 'sensor', 'motor', 'analog']

/** Section names (English sources: shown through tc(name, 'example category')). */
export const EXAMPLE_CATEGORY_NAMES: Record<ExampleCategory, string> = {
  gpio: 'GPIO, timers & PWM',
  serial: 'Serial buses & links',
  display: 'Displays',
  sensor: 'Sensors & input',
  motor: 'Motors & actuators',
  analog: 'Analog & logic classics',
}

/** Difficulty names (English sources: shown through tc(name, 'difficulty')). */
export const EXAMPLE_DIFFICULTY_NAMES: Record<ExampleDifficulty, string> = {
  beginner: 'Beginner',
  intermediate: 'Intermediate',
  advanced: 'Advanced',
}

/** Instrument names (English sources: shown through tc(name, 'example instrument')). */
export const EXAMPLE_INSTRUMENT_NAMES: Record<ExampleInstrument, string> = {
  uart: 'UART terminal',
  logic: 'Logic analyzer',
  scope: 'Oscilloscope',
}

/** Section name in the UI language. */
export function exampleCategoryName(c: ExampleCategory): string {
  return tc(EXAMPLE_CATEGORY_NAMES[c], 'example category')
}

/** Difficulty name in the UI language. */
export function exampleDifficultyName(d: ExampleDifficulty): string {
  return tc(EXAMPLE_DIFFICULTY_NAMES[d], 'difficulty')
}

/** Instrument name in the UI language. */
export function exampleInstrumentName(i: ExampleInstrument): string {
  return tc(EXAMPLE_INSTRUMENT_NAMES[i], 'example instrument')
}

/**
 * The parts-library category whose card tint an example section borrows
 * (the .ws-part.cat-* glyph colours), so example cards read as one kit with
 * the library's part cards.
 */
export const EXAMPLE_CATEGORY_TINT: Record<ExampleCategory, ComponentCategory> = {
  gpio: 'mcu',
  serial: 'instrument',
  display: 'display',
  sensor: 'sensor',
  motor: 'motor',
  analog: 'ic',
}

/** One generated example (examples/embedded/index.json entry). */
export interface EmbeddedExample {
  id: string
  /** envelope file name inside examples/embedded */
  file: string
  category: ExampleCategory
  order: number
  difficulty: ExampleDifficulty
  /** zh-TW content */
  title: string
  summary: string
  /** paragraphs separated by blank lines */
  description: string
  tags: string[]
  /** catalog type whose glyph represents the example */
  glyph: string
  /** firmware/dist project embedded for U1 (null: analog-only circuit) */
  firmware: { project: string; name: string; sha256: string; size: number } | null
  /** 'partial': something is not simulated — simulationNote says exactly what */
  simulation: 'full' | 'partial'
  simulationNote?: string
  parts: number
  wires: number
  instruments: ExampleInstrument[]
}

export const EMBEDDED_EXAMPLES: readonly EmbeddedExample[] = (embeddedIndex as unknown as { examples: EmbeddedExample[] })
  .examples

/** A row of the Examples list (legacy circuit or generated project). */
export interface LibraryExample {
  /** stable key ('legacy:<title>' or the embedded id) */
  key: string
  category: ExampleCategory
  difficulty: ExampleDifficulty
  /**
   * true: title / summary / description are ENGLISH sources (legacy entries,
   * shown through t()); false: zh-TW content shown as is. Read them through
   * exampleTitle() / exampleSummary() / exampleDescription().
   */
  localized: boolean
  title: string
  summary: string
  description: string
  tags: readonly string[]
  glyph: string
  firmware: EmbeddedExample['firmware']
  simulation: 'full' | 'partial'
  simulationNote?: string
  parts: number
  wires: number
  instruments: readonly ExampleInstrument[]
  /** JSON text for lab.importProject (envelope or bare legacy layout) */
  load(): Promise<string>
}

