function legacyInstruments(layout: CircuitLayout): ExampleInstrument[] {
  return layout.components.some((c) => c.type === 'scope_probe') ? ['scope'] : []
}

/** Envelope URLs (Vite static assets; fetched on demand, never in the main bundle). */
const urls = import.meta.glob<string>('/examples/embedded/*.ohmlet.json', { query: '?url', import: 'default' })

/** JSON text of an embedded example's envelope. */
export async function loadEmbeddedExample(file: string): Promise<string> {
  const key = `/examples/embedded/${file}`
  const load = urls[key]
  if (!load) throw new Error(`unknown example file "${file}"`)
  if (typeof window === 'undefined' || typeof fetch === 'undefined') {
    // node (tests): read the file from disk (the base URL through a variable,
    // so Vite's `new URL(…, import.meta.url)` asset transform leaves it alone)
    const { readFileSync } = await import('node:fs')
    const { fileURLToPath } = await import('node:url')
    const here = import.meta.url
    return readFileSync(fileURLToPath(new URL(`../../../examples/embedded/${file}`, here)), 'utf8')
  }
  const res = await fetch(await load())
  if (!res.ok) throw new Error(`could not fetch ${file}: HTTP ${res.status}`)
  return res.text()
}

const legacyEntries: LibraryExample[] = EXAMPLES.map((ex) => {
  const m = LEGACY_META[ex.title]
  return {
    key: `legacy:${ex.title}`,
    category: 'analog',
    difficulty: m?.difficulty ?? 'beginner',
    localized: true,
    title: ex.title,
    summary: m?.summary ?? '',
    description: m?.description ?? '',
    tags: m?.tags ?? [],
    glyph: m?.glyph ?? 'resistor',
    firmware: null,
    simulation: 'full',
    parts: ex.layout.components.length,
    wires: ex.layout.wires.length,
    instruments: legacyInstruments(ex.layout),
    load: async () => JSON.stringify(ex.layout),
  }
})

const embeddedEntries: LibraryExample[] = EMBEDDED_EXAMPLES.map((ex) => ({
  key: ex.id,
  category: ex.category,
  difficulty: ex.difficulty,
  localized: false,
  title: ex.title,
  summary: ex.summary,
  description: ex.description,
  tags: ex.tags,
  glyph: ex.glyph,
  firmware: ex.firmware,
  simulation: ex.simulation,
  simulationNote: ex.simulationNote,
  parts: ex.parts,
  wires: ex.wires,
  instruments: ex.instruments,
  load: () => loadEmbeddedExample(ex.file),
}))

const DIFFICULTY_RANK: Record<ExampleDifficulty, number> = { beginner: 0, intermediate: 1, advanced: 2 }

/**
 * Every example, grouped by category order; inside a category beginner →
 * intermediate → advanced (a class works down the list), then the existing
 * order (generated projects by their order, then the legacy circuits).
 */
export const LIBRARY: readonly LibraryExample[] = EXAMPLE_CATEGORIES.flatMap((c) =>
  [...embeddedEntries.filter((e) => e.category === c), ...legacyEntries.filter((e) => e.category === c)]
    .map((e, i) => ({ e, i }))
    .sort((a, b) => DIFFICULTY_RANK[a.e.difficulty] - DIFFICULTY_RANK[b.e.difficulty] || a.i - b.i)
    .map(({ e }) => e),
)

/** The library split into its non-empty sections. */
export function librarySections(list: readonly LibraryExample[] = LIBRARY): { category: ExampleCategory; examples: LibraryExample[] }[] {
  return EXAMPLE_CATEGORIES.map((category) => ({ category, examples: list.filter((e) => e.category === category) })).filter(
    (s) => s.examples.length > 0,
  )
}

// ---------------------------------------------------------------------------
// Display texts + search
// ---------------------------------------------------------------------------

type Translate = (src: string) => string

/**
 * The canonical term table (UX_VERIFY.md §5.4) applied to an example's own
 * zh-TW text: 「佔空比」 reads 「工作週期」 as in the lessons and instruments
 * (UX fix wave SC-17 — until every generated example says it itself).
 */
function canonicalTerms(text: string): string {
  return text.replace(/佔空比/g, '工作週期')
}

export function exampleTitle(ex: LibraryExample, t: Translate): string {
  return ex.localized ? t(ex.title) : canonicalTerms(ex.title)
}

export function exampleSummary(ex: LibraryExample, t: Translate): string {
  return ex.localized ? t(ex.summary) : canonicalTerms(ex.summary)
}

/**
 * A description paragraph split into runs: `code` spans (literal firmware
 * output, register / command names, identifiers — shown verbatim in mono)
 * and plain zh-TW text. An unmatched backtick stays plain text.
 */
export function exampleTextRuns(paragraph: string): { text: string; code: boolean }[] {
  const out: { text: string; code: boolean }[] = []
  const re = /`([^`\n]+)`/g
  let last = 0
  for (const m of paragraph.matchAll(re)) {
    const i = m.index ?? 0
    if (i > last) out.push({ text: paragraph.slice(last, i), code: false })
    out.push({ text: m[1], code: true })
    last = i + m[0].length
  }
  if (last < paragraph.length) out.push({ text: paragraph.slice(last), code: false })
  return out
}

/** Description paragraphs. */
export function exampleDescription(ex: LibraryExample, t: Translate): string[] {
  const text = ex.localized ? t(ex.description) : canonicalTerms(ex.description)
  return text
    .split(/\n{2,}/)
    .map((p) => p.trim())
    .filter(Boolean)
}

/**
 * Search: every whitespace-separated term must occur (case-insensitive) in
 * the shown title, summary, tags, firmware project or one of `extra` (the
 * localized category / difficulty names).
 */
export function exampleMatches(ex: LibraryExample, query: string, t: Translate, extra: readonly string[] = []): boolean {
  return exampleMatchRank(ex, query, t, extra) >= 0
}

/**
 * How well `ex` matches `query` (UX fix wave SC-17): every term must occur
 * somewhere; the rank is the weakest field a term needed — 0 the title, 1
 * the summary, 2 a tag or the firmware project, 3 only `extra` (the
 * category / difficulty names, a last supplement). −1: no match. An empty
 * query ranks everything 0. Searching 「PWM」 puts 「PWM 呼吸燈」 (title)
 * before the summary hits and the rest of the 「GPIO、計時器與 PWM」 section.
 */
export function exampleMatchRank(ex: LibraryExample, query: string, t: Translate, extra: readonly string[] = []): number {
  const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean)
  if (terms.length === 0) return 0
  const fields = [
    exampleTitle(ex, t).toLowerCase(),
    exampleSummary(ex, t).toLowerCase(),
    [...ex.tags, ex.firmware?.project ?? ''].join('\n').toLowerCase(),
    extra.join('\n').toLowerCase(),
  ]
  let rank = 0
  for (const term of terms) {
    const best = fields.findIndex((f) => f.includes(term))
    if (best < 0) return -1
    rank = Math.max(rank, best)
  }
  return rank
}

// ---------------------------------------------------------------------------
// Opening
// ---------------------------------------------------------------------------

export type ImportProject = (text: string) => Promise<{ ok: boolean; errors: string[]; warnings: string[] }>

/**
 * Load an example into the lab: fetch its JSON and hand it to
 * lab.importProject (layout validated + loaded as one undo step, embedded
 * firmware verified and bound, instrument setup applied). Never throws: a
 * fetch failure comes back as `{ ok: false, errors: [message] }`.
 *
 * Every successful open (Examples tab, More → Examples, openExampleById)
 * then points the workspace's instrument tray at the example's main
 * instrument (showExampleInstrument) — an analog circuit without one leaves
 * the tray as it is.
 */
export async function openLibraryExample(
  ex: LibraryExample,
  importProject: ImportProject,
): Promise<{ ok: boolean; errors: string[]; warnings: string[] }> {
  let text: string
  try {
    text = await ex.load()
  } catch (err) {
    return { ok: false, errors: [err instanceof Error ? err.message : String(err)], warnings: [] }
  }
  const res = await importProject(text)
  if (res.ok) {
    showExampleInstrument(ex)
    makeRoomForCircuit()
  }
  return res
}

/** Below this viewport width a freshly opened example gets the library's space (SC-8). */
export const LIBRARY_COLLAPSE_BELOW_PX = 1500

/**
 * Narrow desktop workspace (< LIBRARY_COLLAPSE_BELOW_PX, e.g. the 1366 ×
 * 768 classroom laptop): collapse the library panel so the circuit just
 * opened gets the room (the scene re-frames into the wider free area), and
 * say how to get the panel back. Lessons never call this — their coach card
 * lives in that panel.
 */
function makeRoomForCircuit(): void {
  if (!isWorkspaceShowing() || typeof window === 'undefined' || window.innerWidth >= LIBRARY_COLLAPSE_BELOW_PX) return
  const lab = useLab.getState()
  if (!lab.workspace.left.open) return
  lab.setWorkspace({ left: { ...lab.workspace.left, open: false } })
  // after the caller's 「已開啟…」 toast
  setTimeout(() => showToast(t('Collapsed the library to give the circuit more room (the handle on the left opens it)'), { duration: 3600 }), 0)
}

/**
 * Open the workspace tray on `ex`'s main instrument (exampleMainInstrument:
 * logic > scope > uart). No instrument → the tray is left as it is.
 */
export function showExampleInstrument(ex: Pick<LibraryExample, 'instruments'>): void {
  const tab = exampleMainInstrument(ex)
  if (!tab) return
  const lab = useLab.getState()
  lab.setWorkspace({ tray: { ...lab.workspace.tray, open: true, tab } })
}

/**
 * The import warnings worth a toast right away: firmware that could not be
 * bound (the example would run without its program). Layout warnings go to
 * the Issues list like any import.
 */
export function firmwareWarnings(warnings: readonly string[]): string[] {
  return warnings.filter((w) => w.startsWith('firmware "'))
}

/** Does replacing `layout` lose anything the user built (any part or wire)? */
export function boardHasContent(layout: Pick<CircuitLayout, 'components' | 'wires'>): boolean {
  return layout.components.length > 0 || layout.wires.length > 0
}

// ---------------------------------------------------------------------------
// Opening by id (UX wave contract K10 — onboarding, empty state, lessons)
// ---------------------------------------------------------------------------

/** The library entry with key `id` ('blink', 'i2c-scan' … or 'legacy:<title>'). */
export function findLibraryExample(id: string): LibraryExample | undefined {
  return LIBRARY.find((ex) => ex.key === id)
}

/**
 * The instrument-tray tab an example is about: the first of its instruments
 * in the order logic > scope > uart; null when it uses none (the tray is
 * then left as it is).
 */
export function exampleMainInstrument(
  ex: Pick<LibraryExample, 'instruments'> & { key?: string },
): Extract<TrayTab, ExampleInstrument> | null {
  // a UART link IS the subject of these: the terminal shows the protocol's
  // content directly (the logic analyzer view of TX / RX is the second look)
  if (ex.key && UART_LINK_EXAMPLES.has(ex.key) && ex.instruments.includes('uart')) return 'uart'
  for (const tab of ['logic', 'scope', 'uart'] as const) if (ex.instruments.includes(tab)) return tab
  return null
}

/** Examples about a UART link itself (open on the UART terminal, not the logic analyzer). */
const UART_LINK_EXAMPLES: ReadonlySet<string> = new Set(['uart-hello', 'ch340-bridge', 'hc05-bluetooth', 'rs485-link'])

/** The latest "show this example's card" request (consumed by the Examples tab: expand + scroll). */
let revealRequest: { key: string; seq: number } | null = null
const revealSubs = new Set<() => void>()

export function exampleRevealRequest(): { key: string; seq: number } | null {
  return revealRequest
}

/** Subscribe to reveal requests; returns the unsubscribe function. */
export function onExampleReveal(fn: () => void): () => void {
  revealSubs.add(fn)
  return () => {
    revealSubs.delete(fn)
  }
}

function requestExampleReveal(key: string): void {
  revealRequest = { key, seq: (revealRequest?.seq ?? 0) + 1 }
  for (const fn of revealSubs) fn()
}

/**
 * Open library example `id` on the board (onboarding 「先看範例」, the empty
 * state, lesson links): lab.importProject through openLibraryExample, with
 * the Examples tab's toasts (「已開啟「…」」 / the error), then the tray
 * switched to the example's main instrument (exampleMainInstrument).
 *
 * `confirmIfNotEmpty`: when the board holds anything, do NOT replace it —
 * show the example's card in the workspace's Examples tab instead (its
 * 「開啟範例」 asks before replacing) and resolve `{ ok: false, pending:
 * 'confirm' }`; phones (no workspace) get the same result and the caller
 * shows its own confirmation. Without it the board is replaced right away
 * (one undo step brings it back).
 */
export async function openExampleById(
  id: string,
  opts: { confirmIfNotEmpty?: boolean } = {},
): Promise<{ ok: boolean; error?: string; pending?: 'confirm' }> {
  const ex = findLibraryExample(id)
  if (!ex) {
    const error = t('Example “{id}” was not found', { id })
    showToast(t('Couldn’t open example: {error}', { error }))
    return { ok: false, error }
  }
  if (opts.confirmIfNotEmpty && boardHasContent(useStore.getState().layout)) {
    if (isWorkspaceShowing()) {
      const lab = useLab.getState()
      lab.setWorkspace({ left: { ...lab.workspace.left, open: true, tab: 'examples' } })
    }
    requestExampleReveal(ex.key)
    return { ok: false, pending: 'confirm' }
  }
  const res = await openLibraryExample(ex, useLab.getState().importProject)
  const title = exampleTitle(ex, t)
  if (!res.ok) {
    const error = res.errors[0] ? tMessage(res.errors[0]) : t('unknown error')
    showToast(t('Couldn’t open example: {error}', { error }))
    return { ok: false, error }
  }
  tick()
  const fw = firmwareWarnings(res.warnings)
  showToast(fw.length > 0 ? t('Opened “{title}” — firmware not loaded: {error}', { title, error: tMessage(fw[0]) }) : t('Opened “{title}”', { title }))
  // (the tray already switched to the example's instrument in openLibraryExample)
  return { ok: true }
}
